(window.KOTOBA_HK=window.KOTOBA_HK||{})[21]={"n":21,"S":[{"id":"l21a","ti":[[["北風","きたかぜ"],["と","と"],["太陽","たいよう"],["の","の"],["勝負","しょうぶ"]]],"tt":{"az":"Şimal küləyi ilə Günəşin yarışı","en":"The Contest Between the North Wind and the Sun","ru":"Соревнование Северного ветра и Солнца"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["空","そら"],["に","に"]],[["北風","きたかぜ"],["と","と"]],[["太陽","たいよう"],["が","が"]],[["いました","いました","いる",2],["。"],["北風","きたかぜ"],["は","は"]],[["とても","とても"]],[["強くて","つよくて","強い",3],["、"],["いつ","いつ"],["も","も"]],[["大きな","おおきな"]],[["声","こえ"],["で","で"]],[["話しました","はなしました","話す",2],["。"],["太陽","たいよう"],["は","は"]],[["静か","しずか"],["で","で"],["、"],["いつ","いつ"],["も","も"]],[["にこにこ","にこにこ"],["していました","していました","する",15],["。"],["ある日","あるひ"],["、"],["北風","きたかぜ"],["は","は"],["「"],["わたし","わたし"],["の","の"]],[["ほう","ほう"],["が","が"]],[["強い","つよい"],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, göydə Şimal küləyi ilə Günəş yaşayırdı. Şimal küləyi çox güclü idi və həmişə ucadan danışırdı. Günəş isə sakit idi və daim gülümsəyirdi. Bir gün Şimal küləyi dedi: «Məncə, mən daha güclüyəm».","en":"Long ago, the North Wind and the Sun lived in the sky. The North Wind was very strong and always spoke loudly. The Sun was quiet and always smiled. One day, the North Wind said, “I think I am stronger.”","ru":"Давным-давно на небе жили Северный ветер и Солнце. Северный ветер был очень сильным и всегда говорил громко. А Солнце было спокойным и всегда улыбалось. Однажды Северный ветер сказал: «Я думаю, что я сильнее»."}},{"t":[[["太陽","たいよう"],["は","は"],["「"],["本当","ほんとう"],["です","です"],["か","か"],["。"],["で","で"],["は","は"],["、"],["勝負","しょうぶ"],["を","を"]],[["しましょう","しましょう","する",20],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ちょうど","ちょうど"]],[["その","その"],["時","とき"],["、"],["一人","ひとり"],["の","の"]],[["男","おとこ"],["の","の"],["人","ひと"],["が","が"]],[["道","みち"],["を","を"]],[["歩いていました","あるいていました","歩く",15],["。"],["男","おとこ"],["の","の"],["人","ひと"],["は","は"]],[["厚い","あつい"]],[["上着","うわぎ"],["を","を"]],[["着ていました","きていました","着る",15],["。"],["北風","きたかぜ"],["は","は"],["「"],["あの","あの"]],[["上着","うわぎ"],["を","を"]],[["脱がせた","ぬがせた","脱ぐ",48]],[["人","ひと"],["が","が"]],[["勝ち","かち"],["でしょう","でしょう","です"],["？"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Günəş dedi: «Doğrudan? Onda yarışaq». Elə həmin vaxt bir kişi yolla gedirdi. Kişi qalın gödəkçə geyinmişdi. Şimal küləyi dedi: «O kişiyə gödəkçəsini çıxartdıra bilən qalib olacaq, elə deyilmi?»","en":"The Sun said, “Really? Then let's have a contest.” Just then, a man was walking along a road. He was wearing a thick coat. The North Wind said, “Whoever makes that man take off his coat wins, right?”","ru":"Солнце сказало: «Правда? Тогда давай посоревнуемся». Как раз в это время по дороге шёл мужчина. На нём была толстая куртка. Северный ветер сказал: «Победит тот, кто заставит его снять куртку, верно?»"}},{"t":[[["北風","きたかぜ"],["が","が"]],[["先","さき"],["に","に"]],[["始めました","はじめました","始める",2],["。"],["「"],["すごい","すごい"]],[["風","かぜ"],["を","を"]],[["見せます","みせます","見せる",11],["よ","よ"],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["強く","つよく","強い"]],[["吹きました","ふきました","吹きました",2],["。"],["道","みち"],["の","の"]],[["木","き"],["が","が"]],[["大きく","おおきく","大きい"]],[["動きました","うごきました","動く",2],["。"],["男","おとこ"],["の","の"],["人","ひと"],["は","は"],["「"],["寒い","さむい"],["です","です"],["ね","ね"],["。"],["気","き"],["を","を"],["つけない","つけない","つける",19],["と","と"],["…"],["…"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["上着","うわぎ"],["を","を"]],[["しっかり","しっかり"]],[["持ちました","もちました","持つ",2],["。"]]],"tr":{"az":"Əvvəlcə Şimal küləyi başladı. «İndi sizə necə güclü külək olduğumu göstərəcəyəm», deyib bərk əsməyə başladı. Yol kənarındakı ağaclar güclü şəkildə yelləndi. Kişi dedi: «Necə də soyuqdur. Ehtiyatlı olmalıyam...» Sonra gödəkçəsindən möhkəm yapışdı.","en":"The North Wind went first. “I'll show you an amazing wind,” he said, and blew hard. The trees beside the road swayed wildly. The man said, “It's cold. I must be careful...” Then he held his coat tightly.","ru":"Первым начал Северный ветер. «Сейчас покажу вам невероятный ветер», сказал он и сильно подул. Деревья у дороги сильно закачались. Мужчина сказал: «Как холодно. Нужно быть осторожным...» Затем он крепко придержал куртку."}},{"t":[[["北風","きたかぜ"],["は","は"]],[["もっと","もっと"]],[["強く","つよく","強い"]],[["吹きました","ふきました","吹きました",2],["。"],["でも","でも"],["、"],["男","おとこ"],["の","の"],["人","ひと"],["は","は"]],[["上着","うわぎ"],["を","を"]],[["脱ぎませんでした","ぬぎませんでした","脱ぐ",4],["。"],["男","おとこ"],["の","の"],["人","ひと"],["は","は"],["「"],["この","この"]],[["風","かぜ"],["は","は"]],[["いつ","いつ"]],[["やむでしょう","やむでしょう"],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"],["北風","きたかぜ"],["は","は"]],[["疲れました","つかれました","疲れる",2],["。"],["「"],["もう","もう"]],[["やめます","やめます","やめます",11],["。"],["太陽さん","たいようさん"],["、"],["どうぞ","どうぞ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Şimal küləyi daha da güclü əsdi. Amma kişi gödəkçəsini çıxarmadı. Kişi düşündü: «Görəsən, bu külək nə vaxt dayanacaq?» Şimal küləyi yoruldu. «Mən dayanıram. Günəş, növbə sənindir», dedi.","en":"The North Wind blew even harder. But the man did not take off his coat. The man thought, “I wonder when this wind will stop.” The North Wind became tired. “I'll stop now. Sun, it's your turn,” he said.","ru":"Северный ветер подул ещё сильнее. Но мужчина не снял куртку. Он подумал: «Интересно, когда же этот ветер стихнет?» Северный ветер устал. «Всё, я прекращаю. Солнце, теперь твоя очередь», сказал он."}},{"t":[[["太陽","たいよう"],["は","は"]],[["ゆっくり","ゆっくり"]],[["顔","かお"],["を","を"]],[["出しました","だしました","出す",2],["。"],["空","そら"],["は","は"]],[["明るく","あかるく","明るい"]],[["なりました","なりました","なる",2],["。"],["男","おとこ"],["の","の"],["人","ひと"],["は","は"],["「"],["ああ","ああ"],["、"],["いい","いい"]],[["天気","てんき"],["に","に"]],[["なりました","なりました","なる",2],["ね","ね"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["太陽","たいよう"],["は","は"],["「"],["暖かい","あたたかい"]],[["日","ひ"],["は","は"]],[["気持ち","きもち"],["が","が"]],[["いい","いい"],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["小さな","ちいさな"]],[["声","こえ"],["で","で"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Günəş yavaş-yavaş buludların arasından göründü. Göy üzü işıqlandı. Kişi dedi: «Ah, hava necə də gözəlləşdi!» Günəş sakit səslə dedi: «Məncə, isti günlər insana xoş gəlir».","en":"The Sun slowly appeared from behind the clouds. The sky became bright. The man said, “Ah, the weather has become lovely!” The Sun said softly, “I think warm days feel wonderful.”","ru":"Солнце медленно выглянуло из-за облаков. Небо стало светлым. Мужчина сказал: «Ах, какая хорошая стала погода!» Солнце тихо произнесло: «Думаю, в тёплые дни людям приятно»."}},{"t":[[["道","みち"],["の","の"]],[["近く","ちかく"],["に","に"]],[["小さな","ちいさな"]],[["公園","こうえん"],["が","が"]],[["ありました","ありました","ある",2],["。"],["その","その"]],[["公園","こうえん"],["で","で"]],[["花","はな"],["の","の"]],[["お祭り","おまつり"],["が","が"]],[["ありました","ありました","ある",2],["。"],["男","おとこ"],["の","の"],["人","ひと"],["は","は"]],[["少し","すこし"]],[["休もう","やすもう","休む",7],["と","と"]],[["思いました","おもいました","思う",2],["。"],["「"],["上着","うわぎ"],["は","は"]],[["もう","もう"]],[["いりません","いりません","いる",6],["ね","ね"],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["上着","うわぎ"],["を","を"]],[["脱ぎました","ぬぎました","脱ぐ",2],["。"],["そして","そして"],["、"],["木","き"],["の","の"]],[["下","した"],["で","で"]],[["お茶","おちゃ"],["を","を"]],[["飲みました","のみました","飲む",2],["。"]]],"tr":{"az":"Yolun yaxınlığında kiçik bir park var idi. Həmin parkda gül festivalı keçirilirdi. Kişi bir az dincəlmək istədi. «Artıq gödəkçəyə ehtiyac yoxdur», deyib onu çıxardı. Sonra ağacın altında çay içdi.","en":"There was a small park near the road. A flower festival was being held there. The man decided to rest for a while. “I don't need my coat anymore,” he said, taking it off. Then he drank tea beneath a tree.","ru":"Рядом с дорогой был маленький парк. Там проходил фестиваль цветов. Мужчина решил немного отдохнуть. «Куртка мне больше не нужна», сказал он и снял её. Затем он выпил чай под деревом."}},{"t":[[["北風","きたかぜ"],["は","は"]],[["びっくり","びっくり"],["しました","しました","する",2],["。"],["「"],["わたし","わたし"],["は","は"]],[["負けました","まけました","負けました",2],["。"],["太陽さん","たいようさん"],["が","が"]],[["勝ちました","かちました","勝ちました",2],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["太陽","たいよう"],["は","は"],["「"],["強い","つよい"]],[["力","ちから"],["だけ","だけ"],["で","で"],["は","は"]],[["だめ","だめ"],["だ","だ","です"],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["北風","きたかぜ"],["は","は"],["「"],["本当","ほんとう"],["です","です"],["ね","ね"],["。"],["優しい","やさしい"]],[["力","ちから"],["も","も"]],[["役","やく"],["に","に"]],[["立ちます","たちます","立つ",11],["ね","ね"],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Şimal küləyi çox təəccübləndi. «Mən uduzdum. Günəş qalib gəldi», dedi. Günəş dedi: «Məncə, təkcə güc kifayət etmir». Şimal küləyi cavab verdi: «Doğrudur. Yumşaqlıq da faydalı ola bilər».","en":"The North Wind was astonished. “I lost. The Sun won,” he said. The Sun replied, “I think strength alone is not enough.” The North Wind answered, “That's true. Gentleness can be useful too.”","ru":"Северный ветер удивился. «Я проиграл. Солнце победило», сказал он. Солнце ответило: «Думаю, одной силы недостаточно». Северный ветер согласился: «Это правда. Мягкость тоже может быть полезной»."}},{"t":[[["その","その"]],[["夕方","ゆうがた"],["、"],["空","そら"],["で","で"]],[["小さな","ちいさな"]],[["お祝い","おいわい"],["が","が"]],[["ありました","ありました","ある",2],["。"],["北風","きたかぜ"],["は","は"],["「"],["明日","あした"],["は","は"]],[["優しく","やさしく","優しい"]],[["吹こう","ふこう","吹こう",7],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["次","つぎ"],["の","の"]],[["朝","あさ"],["、"],["北風","きたかぜ"],["は","は"]],[["また","また"]],[["大きな","おおきな"]],[["声","こえ"],["で","で"],["「"],["おはよう","おはよう"],["！"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["町","まち"],["の","の"]],[["人たち","ひとたち"],["は","は"]],[["みんな","みんな"]],[["目","め"],["を","を"]],[["覚ましました","さましました","覚ましました",2],["。"],["太陽","たいよう"],["は","は"]],[["笑って","わらって","笑う",3],["、"],["「"],["元気な","げんきな","元気",1]],[["風","かぜ"],["です","です"],["ね","ね"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Həmin axşam göydə kiçik bir şənlik oldu. Şimal küləyi dedi: «Sabah yumşaq əsəcəyəm». Amma səhəri gün yenə gur səslə «Sabahınız xeyir!» deyə qışqırdı. Şəhərdə hamı yuxudan oyandı. Günəş gülərək dedi: «Nə enerjili küləkdir!»","en":"That evening, there was a little celebration in the sky. The North Wind said, “I think I'll blow gently tomorrow.” But the next morning, he shouted, “Good morning!” in his booming voice again. Everyone in town woke up. The Sun laughed and said, “What an energetic wind!”","ru":"В тот вечер на небе устроили маленький праздник. Северный ветер сказал: «Завтра я постараюсь дуть мягко». Но на следующее утро он снова громко закричал: «Доброе утро!» Все жители города проснулись. Солнце засмеялось и сказало: «Какой энергичный ветер!»"}}]},{"id":"l21b","ti":[[["雨","あめ"],["を","を"]],[["作る","つくる","作る",5]],[["少女","しょうじょ"],["と","と"]],[["青い","あおい"]],[["空","そら"]]],"tt":{"az":"Yağış yaradan qız və mavi səma","en":"The Girl Who Made Rain and the Blue Sky","ru":"Девочка, вызывавшая дождь, и голубое небо"},"P":[{"t":[[["山","やま"],["の","の"]],[["近く","ちかく"],["の","の"]],[["小さな","ちいさな"]],[["町","まち"],["に","に"],["、"],["ユナ","ユナ"],["と","と"],["いう","いう","いう",5]],[["女の子","おんなのこ"],["が","が"]],[["住んでいました","すんでいました","住む",31],["。"],["ユナ","ユナ"],["に","に"],["は","は"]],[["不思議な","ふしぎな","不思議",1]],[["力","ちから"],["が","が"]],[["ありました","ありました","ある",2],["。"],["「"],["雨","あめ"],["が","が"]],[["降る","ふる","降る",5],["」"],["と","と"]],[["思う","おもう","思う",5],["と","と"],["、"],["本当","ほんとう"],["に","に"]],[["雨","あめ"],["が","が"]],[["降りました","ふりました","降る",2],["。"],["でも","でも"],["、"],["ユナ","ユナ"],["は","は"]],[["その","その"]],[["力","ちから"],["を","を"]],[["だれ","だれ"],["に","に"],["も","も"]],[["言いませんでした","いいませんでした","言う",4],["。"],["みんな","みんな"],["が","が"]],[["うそ","うそ"],["だ","だ","です"],["と","と"]],[["思うでしょう","おもうでしょう","思う"],["。"]]],"tr":{"az":"Dağın yaxınlığındakı balaca bir şəhərdə Yuna adlı qız yaşayırdı. Yunanın qəribə bir gücü var idi. O, «Yağış yağacaq» deyə düşünəndə həqiqətən yağış yağırdı. Amma Yuna bu sirri heç kimə demirdi. Çünki hamının bunu yalan hesab edəcəyini düşünürdü.","en":"In a small town near the mountains lived a girl named Yuna. She had a mysterious power. Whenever she thought, “It will rain,” rain really fell. But Yuna told nobody about her power. She believed everyone would think it was a lie.","ru":"В маленьком городке у гор жила девочка по имени Юна. У неё была таинственная сила. Стоило ей подумать: «Пойдёт дождь», как дождь действительно начинался. Но Юна никому не рассказывала о своём даре. Она считала, что все решат, будто это неправда."}},{"t":[[["ある","ある","ある(連体詞)"]],[["夏","なつ"],["、"],["町","まち"],["で","で"],["は","は"]],[["雨","あめ"],["が","が"]],[["一か月","いっかげつ"],["も","も"]],[["降りませんでした","ふりませんでした","降る",4],["。"],["川","かわ"],["の","の"]],[["水","みず"],["が","が"]],[["少なく","すくなく"]],[["なり","なり","なる",10],["、"],["花","はな"],["も","も"]],[["元気","げんき"],["が","が"]],[["なくなりました","なくなりました","なくなりました",2],["。"],["テレビ","テレビ"],["の","の"]],[["ニュース","ニュース"],["で","で"],["「"],["今年","ことし"],["は","は"]],[["とても","とても"]],[["暑いでしょう","あついでしょう","暑い"],["」"],["と","と"]],[["言っていました","いっていました","言う",15],["。"],["ユナ","ユナ"],["は","は"],["「"],["雨","あめ"],["を","を"]],[["降らせない","ふらせない","降る",49],["と","と"],["…"],["…"],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"]]],"tr":{"az":"Bir yay şəhərdə düz bir ay yağış yağmadı. Çayda su azaldı, güllər də solmağa başladı. Televiziya xəbərlərində «Bu il çox isti olacaq» deyilirdi. Yuna düşündü: «Mütləq yağış yağdırmalıyam...»","en":"One summer, no rain fell in the town for an entire month. The river grew shallow, and the flowers began to wilt. On the television news, they said, “This year will probably be very hot.” Yuna thought, “I have to make it rain...”","ru":"Однажды летом в городе целый месяц не было дождя. В реке стало мало воды, а цветы начали увядать. По телевизору в новостях говорили: «В этом году, вероятно, будет очень жарко». Юна подумала: «Нужно обязательно вызвать дождь...»"}},{"t":[[["次","つぎ"],["の","の"]],[["日","ひ"],["、"],["町","まち"],["の","の"]],[["広場","ひろば"],["で","で"]],[["大きな","おおきな"]],[["お祭り","おまつり"],["が","が"]],[["ありました","ありました","ある",2],["。"],["ユナ","ユナ"],["は","は"],["「"],["今","いま"]],[["雨","あめ"],["を","を"]],[["降らせたら","ふらせたら","降る",50],["、"],["みんな","みんな"],["が","が"]],[["困るでしょう","こまるでしょう","困る"],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"],["でも","でも"],["、"],["花","はな"],["の","の"]],[["ため","ため"],["に","に"]],[["水","みず"],["が","が"]],[["必要","ひつよう"],["でした","でした","です",9],["。"],["ユナ","ユナ"],["は","は"]],[["公園","こうえん"],["で","で"]],[["一人","ひとり"],["で","で"]],[["空","そら"],["を","を"]],[["見ました","みました","見る",2],["。"],["そして","そして"],["、"],["小さな","ちいさな"]],[["声","こえ"],["で","で"],["「"],["雨","あめ"],["よ","よ"],["、"],["来て","きて","来る",3],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Ertəsi gün şəhər meydanında böyük festival keçirilirdi. Yuna düşündü: «İndi yağış yağdırsam, hamı çətin vəziyyətdə qalar, elə deyilmi?» Amma güllərin suya ehtiyacı var idi. Yuna parkda təkbaşına göyə baxdı. Sonra astadan dedi: «Yağış, gəl».","en":"The next day, a big festival was being held in the town square. Yuna thought, “If I make it rain now, everyone will have trouble, won't they?” But the flowers needed water. Yuna looked up at the sky alone in the park. Then she whispered, “Rain, please come.”","ru":"На следующий день на городской площади проходил большой праздник. Юна подумала: «Если сейчас вызвать дождь, всем будет неудобно, правда?» Но цветам была нужна вода. Юна одна стояла в парке и смотрела на небо. Затем тихо сказала: «Дождик, приходи»."}},{"t":[[["空","そら"],["に","に"]],[["黒い","くろい"]],[["雲","くも"],["が","が"]],[["集まりました","あつまりました","集まりました",2],["。"],["雨","あめ"],["が","が"]],[["少し","すこし"],["ずつ","ずつ"]],[["降り","ふり","降る",10],["始めました","はじめました","始める",2],["。"],["ところ","ところ"],["が","が"],["、"],["ユナ","ユナ"],["が","が"]],[["くしゃみ","くしゃみ"],["を","を"]],[["する","する","する",5],["と","と"],["、"],["雨","あめ"],["が","が"]],[["急","きゅう"],["に","に"]],[["強く","つよく","強い"]],[["なりました","なりました","なる",2],["。"],["お祭り","おまつり"],["の","の"]],[["人たち","ひとたち"],["は","は"],["「"],["すごい","すごい"]],[["雨","あめ"],["だ","だ","です"],["！"],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["走りました","はしりました","走る",2],["。"],["ユナ","ユナ"],["は","は"],["「"],["たいへんな","たいへんな","たいへんな",1]],[["こと","こと"],["に","に"]],[["なった","なった","なる",0],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"]]],"tr":{"az":"Göydə qara buludlar toplandı. Yavaş-yavaş yağış başladı. Amma Yuna asqıran kimi yağış birdən gücləndi. Festivaldakı insanlar «Nə güclü yağışdır!» deyərək qaçışdılar. Yuna düşündü: «İşlər pis getdi!»","en":"Dark clouds gathered in the sky. Rain began falling little by little. But when Yuna sneezed, the rain suddenly became heavy. People at the festival shouted, “What incredible rain!” and ran for shelter. Yuna thought, “This has become a disaster!”","ru":"На небе собрались тёмные облака. Постепенно начался дождь. Но когда Юна чихнула, дождь внезапно усилился. Люди на празднике закричали: «Какой сильный дождь!» и побежали прятаться. Юна подумала: «Вот это беда!»"}},{"t":[[["その","その"]],[["時","とき"],["、"],["小さな","ちいさな"]],[["男の子","おとこのこ"],["が","が"]],[["雨","あめ"],["の","の"]],[["中","なか"],["で","で"]],[["泣いていました","ないていました","泣く",15],["。"],["男の子","おとこのこ"],["の","の"]],[["赤い","あかい"]],[["かさ","かさ"],["が","が"]],[["風","ふう"],["で","で"]],[["飛んでしまいました","とんでしまいました","飛ぶ",51],["。"],["ユナ","ユナ"],["は","は"],["「"],["助けない","たすけない","助ける",19],["と","と"],["…"],["…"],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["男の子","おとこのこ"],["の","の"]],[["ところ","ところ"],["へ","へ"]],[["走りました","はしりました","走る",2],["。"],["二人","ふたり"],["は","は"]],[["大きな","おおきな"]],[["木","き"],["の","の"]],[["下","した"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["男の子","おとこのこ"],["は","は"],["「"],["お姉さん","おねえさん"],["、"],["ありがとう","ありがとう"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Elə bu vaxt balaca bir oğlan yağışın altında ağlayırdı. Onun qırmızı çətirini külək aparmışdı. Yuna «Ona kömək etməliyəm...» deyərək oğlanın yanına qaçdı. İkisi böyük bir ağacın altına getdi. Oğlan dedi: «Çox sağ ol, bacı».","en":"Just then, a little boy was crying in the rain. The wind had blown away his red umbrella. “I have to help him...” Yuna said, running toward him. They went beneath a large tree. The boy said, “Thank you, big sister.”","ru":"В этот момент маленький мальчик плакал под дождём. Ветер унёс его красный зонтик. «Нужно помочь ему...» сказала Юна и побежала к мальчику. Они укрылись под большим деревом. Мальчик сказал: «Спасибо, сестрёнка»."}},{"t":[[["男の子","おとこのこ"],["は","は"],["「"],["この","この"]],[["雨","あめ"],["は","は"]],[["いつ","いつ"]],[["やむ","やむ","やむ",5],["と","と"]],[["思います","おもいます","思う",11],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["ユナ","ユナ"],["は","は"],["「"],["もう","もう"],["すぐ","すぐ"]],[["やむ","やむ","やむ",5],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["答えました","こたえました","答える",2],["。"],["そして","そして"],["、"],["心","こころ"],["の","の"]],[["中","なか"],["で","で"],["「"],["青い","あおい"]],[["空","そら"],["に","に"]],[["なって","なって","なる",3],["」"],["と","と"]],[["強く","つよく","強い"]],[["思いました","おもいました","思う",2],["。"],["する","する","する",5],["と","と"],["、"],["雨","あめ"],["が","が"]],[["や","や"],["ん","ん"],["で","で"],["、"],["雲","くも"],["が","が"]],[["ゆっくり","ゆっくり"]],[["動きました","うごきました","動く",2],["。"],["空","そら"],["に","に"]],[["大きな","おおきな"]],[["虹","にじ"],["が","が"]],[["出ました","でました","出る",2],["。"]]],"tr":{"az":"Oğlan soruşdu: «Səncə, bu yağış nə vaxt dayanacaq?» Yuna cavab verdi: «Məncə, bir azdan dayanacaq». Sonra ürəyində güclü şəkildə «Qoy səma mavi olsun!» deyə düşündü. Yağış dayandı və buludlar yavaş-yavaş çəkildi. Göydə böyük bir göy qurşağı göründü.","en":"The boy asked, “When do you think this rain will stop?” Yuna answered, “I think it will stop soon.” Then she wished with all her heart, “Let the sky turn blue!” The rain stopped, and the clouds slowly moved away. A great rainbow appeared in the sky.","ru":"Мальчик спросил: «Как думаешь, когда закончится дождь?» Юна ответила: «Думаю, скоро». Затем она всем сердцем пожелала: «Пусть небо станет голубым!» Дождь прекратился, и облака медленно разошлись. На небе появилась огромная радуга."}},{"t":[[["町","まち"],["の","の"]],[["人たち","ひとたち"],["は","は"]],[["虹","にじ"],["を","を"]],[["見て","みて","見る",3],["、"],["喜びました","よろこびました","喜ぶ",2],["。"],["お祭り","おまつり"],["の","の"]],[["放送","ほうそう"],["で","で"],["「"],["雨","あめ"],["の","の"]],[["おかげ","おかげ"],["で","で"],["、"],["町","まち"],["の","の"]],[["花","はな"],["が","が"]],[["元気","げんき"],["に","に"]],[["なりました","なりました","なる",2],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["男の子","おとこのこ"],["は","は"]],[["ユナ","ユナ"],["を","を"]],[["見て","みて","見る",3],["、"],["「"],["お姉さん","おねえさん"],["は","は"]],[["天才","てんさい"],["でしょう","でしょう","です"],["？"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["ユナ","ユナ"],["は","は"]],[["笑って","わらって","笑う",3],["、"],["「"],["いいえ","いいえ"],["、"],["ただ","ただ"],["の","の"]],[["女の子","おんなのこ"],["です","です"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Şəhər sakinləri göy qurşağını görüb sevindilər. Festivalın səsgücləndiricisindən elan edildi: «Yağış sayəsində şəhərimizin gülləri canlandı». Oğlan Yunaya baxıb soruşdu: «Sən dahisən, elə deyilmi?» Yuna gülümsəyib dedi: «Yox, mən adi bir qızam».","en":"The townspeople saw the rainbow and cheered. An announcement at the festival said, “Thanks to the rain, the town's flowers are healthy again.” The boy looked at Yuna and asked, “You're a genius, aren't you?” Yuna smiled and said, “No, I'm just an ordinary girl.”","ru":"Жители города увидели радугу и обрадовались. На празднике по громкоговорителю объявили: «Благодаря дождю наши цветы снова ожили». Мальчик посмотрел на Юну и спросил: «Ты ведь гений, правда?» Юна улыбнулась и ответила: «Нет, я обычная девочка»."}},{"t":[[["次","つぎ"],["の","の"]],[["朝","あさ"],["、"],["ユナ","ユナ"],["の","の"]],[["家","いえ"],["の","の"]],[["前","まえ"],["に","に"]],[["小さな","ちいさな"]],[["花","はな"],["が","が"]],[["ありました","ありました","ある",2],["。"],["そば","そば"],["に","に"],["「"],["雨","あめ"],["を","を"]],[["ありがとう","ありがとう"],["」"],["と","と"]],[["書いた","かいた","書く",0]],[["紙","かみ"],["が","が"]],[["ありました","ありました","ある",2],["。"],["ユナ","ユナ"],["は","は"],["「"],["だれ","だれ"],["が","が"]],[["置いた","おいた","置く",0],["の","の"],["でしょう","でしょう","です"],["」"],["と","と"]],[["思いました","おもいました","思う",2],["。"],["空","そら"],["を","を"]],[["見る","みる","見る",5],["と","と"],["、"],["小さな","ちいさな"]],[["雲","くも"],["が","が"]],[["ハート","ハート"],["の","の"]],[["形","かたち"],["に","に"]],[["なっていました","なっていました","なる",15],["。"],["ユナ","ユナ"],["は","は"],["「"],["雲","くも"],["も","も"]],[["友達","ともだち"],["に","に"]],[["なった","なった","なる",0],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["言って","いって","言う",3],["、"],["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Ertəsi səhər Yunanın evinin qarşısında balaca bir gül var idi. Yanında «Yağış üçün təşəkkürlər» yazılmış kağız qoyulmuşdu. Yuna düşündü: «Görəsən, bunu kim qoyub?» Göyə baxanda ürək şəklində balaca bir bulud gördü. Yuna gülərək dedi: «Məncə, buludlar da mənim dostum oldu».","en":"The next morning, a little flower lay in front of Yuna's house. Beside it was a note saying, “Thank you for the rain.” Yuna wondered, “Who could have left this?” Looking up, she saw a small cloud shaped like a heart. Yuna laughed and said, “I think the clouds have become my friends too.”","ru":"На следующее утро перед домом Юны лежал маленький цветок. Рядом была записка: «Спасибо за дождь». Юна подумала: «Интересно, кто это оставил?» Она посмотрела на небо и увидела маленькое облако в форме сердца. Юна рассмеялась и сказала: «Кажется, облака тоже стали моими друзьями»."}}]},{"id":"l21c","ti":[[["おじいさん","おじいさん"],["の","の"]],[["ひみつ","ひみつ"],["の","の"]],[["ニュース","ニュース"]]],"tt":{"az":"Babanın sirli xəbərləri","en":"Grandpa's Secret News","ru":"Секретные новости дедушки"},"P":[{"t":[[["ある","ある","ある(連体詞)"]],[["町","まち"],["に","に"],["、"],["ケン","ケン"],["と","と"],["いう","いう","いう",5]],[["男の子","おとこのこ"],["が","が"]],[["住んでいました","すんでいました","住む",31],["。"],["ケン","ケン"],["は","は"]],[["毎朝","まいあさ"],["、"],["テレビ","テレビ"],["の","の"]],[["ニュース","ニュース"],["を","を"]],[["見ました","みました","見る",2],["。"],["そして","そして"],["、"],["「"],["世界","せかい"],["で","で"]],[["何","なん"],["が","が"]],[["あった","あった","ある",0],["か","か"]],[["知る","しる","知る",5],["こと","こと"],["は","は"]],[["大切","たいせつ"],["だ","だ","です"],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["いっしょ","いっしょ"],["に","に"]],[["住んでいる","すんでいる","住む",45]],[["おじいさん","おじいさん"],["は","は"]],[["テレビ","テレビ"],["を","を"]],[["あまり","あまり"]],[["見ませんでした","みませんでした","見る",4],["。"]]],"tr":{"az":"Bir şəhərdə Ken adlı oğlan yaşayırdı. Ken hər səhər televizorda xəbərlərə baxırdı. Sonra deyirdi: «Məncə, dünyada nə baş verdiyini bilmək vacibdir». Amma onunla birlikdə yaşayan babası televizora çox baxmırdı.","en":"In a certain town lived a boy named Ken. Every morning, Ken watched the television news. He would say, “I think it's important to know what's happening in the world.” But his grandfather, who lived with him, hardly watched television.","ru":"В одном городе жил мальчик по имени Кэн. Каждое утро Кэн смотрел новости по телевизору. Он говорил: «Я думаю, важно знать, что происходит в мире». Но его дедушка, который жил вместе с ним, почти не смотрел телевизор."}},{"t":[[["おじいさん","おじいさん"],["は","は"]],[["毎朝","まいあさ"],["、"],["公園","こうえん"],["へ","へ"]],[["散歩","さんぽ"],["に","に"]],[["行きました","いきました","行く",2],["。"],["帰る","かえる","帰る",5],["と","と"],["、"],["いつ","いつ"],["も","も"],["「"],["今日","きょう"],["も","も"]],[["いい","いい"]],[["ニュース","ニュース"],["が","が"]],[["あった","あった","ある",0],["よ","よ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ケン","ケン"],["は","は"],["「"],["テレビ","テレビ"],["で","で"]],[["何","なん"],["も","も"]],[["言っていませんでした","いっていませんでした","言う",28],["よ","よ"],["。"],["うそ","うそ"],["でしょう","でしょう","です"],["？"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["本当","ほんとう"],["だ","だ","です"],["よ","よ"],["」"],["と","と"]],[["笑いました","わらいました","笑う",2],["。"]]],"tr":{"az":"Babası hər səhər parkda gəzməyə gedirdi. Qayıdanda həmişə «Bu gün də yaxşı xəbər var!» deyirdi. Ken soruşurdu: «Amma televizorda heç nə demədilər. Zarafat edirsən, elə deyilmi?» Babası gülərək «Yox, doğrudur» deyirdi.","en":"Grandpa went for a walk in the park every morning. Whenever he returned, he said, “There was good news today too!” Ken would ask, “But they didn't say anything on television. You're joking, aren't you?” Grandpa laughed and said, “It's true.”","ru":"Каждое утро дедушка ходил гулять в парк. Вернувшись, он всегда говорил: «Сегодня снова были хорошие новости!» Кэн спрашивал: «Но по телевизору ничего не говорили. Ты ведь шутишь?» Дедушка смеялся и отвечал: «Это правда»."}},{"t":[[["ある","ある","ある(連体詞)"]],[["日","ひ"],["、"],["町","まち"],["の","の"]],[["学校","がっこう"],["で","で"]],[["ニュース","ニュース"],["の","の"]],[["発表","はっぴょう"],["会","かい"],["が","が"]],[["ありました","ありました","ある",2],["。"],["先生","せんせい"],["は","は"],["「"],["みなさん","みなさん"],["、"],["何","なん"],["か","か"]],[["おもしろい","おもしろい"]],[["ニュース","ニュース"],["を","を"]],[["持って","もって","持つ",3]],[["来て","きて","来る",3]],[["ください","ください","くださる",10],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ケン","ケン"],["は","は"]],[["自動車","じどうしゃ"],["や","や"]],[["交通","こうつう"],["の","の"]],[["ニュース","ニュース"],["を","を"]],[["調べました","しらべました","調べる",2],["。"],["でも","でも"],["、"],["友達","ともだち"],["は","は"]],[["みんな","みんな"]],[["同じ","おなじ"]],[["ニュース","ニュース"],["を","を"]],[["持って","もって","持つ",3]],[["来ました","きました","来る",2],["。"]]],"tr":{"az":"Bir gün şəhərdəki məktəbdə xəbərlərin təqdimatı keçiriləcəkdi. Müəllim dedi: «Uşaqlar, maraqlı bir xəbər tapıb gətirin». Ken avtomobillər və nəqliyyat haqqında xəbərləri araşdırdı. Amma bütün dostları da eyni xəbərləri gətirdi.","en":"One day, the town's school held a news presentation. The teacher said, “Everyone, please bring an interesting news story.” Ken researched news about cars and traffic. But all his friends brought the same news stories.","ru":"Однажды в городской школе проходило мероприятие с выступлениями о новостях. Учитель сказал: «Ребята, принесите какую-нибудь интересную новость». Кэн изучил новости об автомобилях и дорожном движении. Но все его друзья принесли те же самые новости."}},{"t":[[["ケン","ケン"],["は","は"]],[["家","いえ"],["で","で"],["「"],["何","なん"],["か","か"]],[["新しい","あたらしい"]],[["ニュース","ニュース"],["が","が"]],[["ない","ない"],["と","と"],["…"],["…"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["公園","こうえん"],["の","の"]],[["ニュース","ニュース"],["でも","でも"]],[["いいでしょう","いいでしょう","いい"],["？"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["ケン","ケン"],["は","は"],["「"],["公園","こうえん"],["で","で"]],[["何","なん"],["が","が"]],[["あった","あった","ある",0],["ん","ん"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["明日","あした"],["の","の"]],[["朝","あさ"],["、"],["いっしょ","いっしょ"],["に","に"]],[["来","き","来る",10],["なさい","なさい","なさる",10],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Ken evdə dedi: «Mənə fərqli bir xəbər lazımdır...» Babası soruşdu: «Parkdan bir xəbər də olar, elə deyilmi?» Ken təəccüblə soruşdu: «Parkda nə baş verib ki?» Babası dedi: «Sabah səhər mənimlə gəl».","en":"At home, Ken said, “I need some new news...” Grandpa asked, “News from the park would be fine too, wouldn't it?” Ken asked, “What happened in the park?” Grandpa said, “Come with me tomorrow morning.”","ru":"Дома Кэн сказал: «Мне нужна какая-нибудь новая новость...» Дедушка спросил: «Новости из парка тоже подойдут, правда?» Кэн удивился: «А что случилось в парке?» Дедушка сказал: «Завтра утром пойдём вместе»."}},{"t":[[["次","つぎ"],["の","の"]],[["朝","あさ"],["、"],["二人","ふたり"],["は","は"]],[["公園","こうえん"],["へ","へ"]],[["行きました","いきました","行く",2],["。"],["公園","こうえん"],["で","で"],["は","は"]],[["小さな","ちいさな"]],[["犬","いぬ"],["が","が"]],[["元気","げんき"],["に","に"]],[["走っていました","はしっていました","走る",15],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["この","この"]],[["犬","いぬ"],["は","は"]],[["昨日","きのう"],["まで","まで"]],[["歩く","あるく","歩く",5],["こと","こと"],["が","が"]],[["できませんでした","できませんでした","できる",4],["。"],["でも","でも"],["、"],["今日","きょう"],["は","は"]],[["走っています","はしっています","走る",24],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ケン","ケン"],["は","は"],["「"],["すごい","すごい"],["！"]],[["本当","ほんとう"],["に","に"]],[["いい","いい"]],[["ニュース","ニュース"],["です","です"],["ね","ね"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Ertəsi səhər ikisi parka getdi. Parkda balaca bir it sevinclə qaçırdı. Babası dedi: «Bu it dünənə qədər yeriyə bilmirdi. Amma bu gün qaçır». Ken dedi: «Möhtəşəmdir! Bu, həqiqətən yaxşı xəbərdir!»","en":"The next morning, they went to the park together. A little dog was running happily. Grandpa said, “Until yesterday, this dog couldn't walk. But today it's running.” Ken exclaimed, “Amazing! That really is good news!”","ru":"На следующее утро они вместе пошли в парк. Там весело бегала маленькая собака. Дедушка сказал: «До вчерашнего дня эта собака не могла ходить. А сегодня она бегает». Кэн воскликнул: «Невероятно! Это действительно хорошая новость!»"}},{"t":[[["公園","こうえん"],["の","の"]],[["奥","おく"],["で","で"],["は","は"],["、"],["小さな","ちいさな"]],[["女の子","おんなのこ"],["が","が"]],[["自転車","じてんしゃ"],["に","に"]],[["乗っていました","のっていました","乗る",15],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["この","この"]],[["子","こ"],["は","は"]],[["一週間","いっしゅうかん"],["も","も"]],[["練習","れんしゅう"],["しました","しました","する",2],["。"],["今日","きょう"],["、"],["初めて","はじめて"]],[["一人","ひとり"],["で","で"]],[["乗れました","のれました","乗れました",2],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["ケン","ケン"],["は","は"],["「"],["テレビ","テレビ"],["の","の"]],[["ニュース","ニュース"],["より","より"]],[["おもしろい","おもしろい"],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["小さな","ちいさな"]],[["メモ","メモ"],["に","に"]],[["その","その"]],[["話","はなし"],["を","を"]],[["書きました","かきました","書く",2],["。"]]],"tr":{"az":"Parkın o biri tərəfində balaca bir qız velosiped sürürdü. Babası dedi: «Bu qız bir həftə məşq etdi. Bu gün ilk dəfə təkbaşına sürə bildi». Ken dedi: «Məncə, bu, televizordakı xəbərlərdən daha maraqlıdır». Sonra həmin əhvalatı balaca dəftərçəsinə yazdı.","en":"Farther inside the park, a little girl was riding a bicycle. Grandpa said, “She practiced for a whole week. Today, for the first time, she rode all by herself.” Ken said, “I think this is more interesting than television news.” Then he wrote the story in his little notebook.","ru":"В глубине парка маленькая девочка каталась на велосипеде. Дедушка сказал: «Она тренировалась целую неделю. Сегодня впервые смогла поехать сама». Кэн сказал: «Думаю, это интереснее новостей по телевизору». Затем он записал эту историю в маленький блокнот."}},{"t":[[["学校","がっこう"],["の","の"]],[["発表","はっぴょう"],["会","かい"],["で","で"],["、"],["ケン","ケン"],["は","は"]],[["公園","こうえん"],["の","の"]],[["ニュース","ニュース"],["を","を"]],[["話しました","はなしました","話す",2],["。"],["「"],["小さな","ちいさな"]],[["幸せ","しあわせ"],["も","も"]],[["大切な","たいせつな","大切",1]],[["ニュース","ニュース"],["だ","だ","です"],["と","と"]],[["思います","おもいます","思う",11],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["先生","せんせい"],["は","は"],["「"],["とても","とても"]],[["いい","いい"]],[["考え","かんがえ"],["です","です"],["ね","ね"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["友達","ともだち"],["も","も"],["「"],["明日","あした"],["は","は"]],[["わたしたち","わたしたち"],["も","も"]],[["町","まち"],["の","の"]],[["ニュース","ニュース"],["を","を"]],[["探しましょう","さがしましょう","探しましょう",20],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Məktəbdəki təqdimatda Ken parkdan topladığı xəbərləri danışdı. «Məncə, kiçik xoşbəxtliklər də vacib xəbərdir», dedi. Müəllim «Çox gözəl fikirdir» söylədi. Dostları da dedilər: «Sabah biz də şəhərimizdəki xəbərləri axtaraq!»","en":"At the school presentation, Ken shared the news from the park. “I think small moments of happiness are important news too,” he said. The teacher replied, “That's a wonderful idea.” His friends said, “Tomorrow, let's look for news around our town too!”","ru":"На школьном выступлении Кэн рассказал новости из парка. «Я думаю, маленькие радости тоже важные новости», сказал он. Учитель ответил: «Очень хорошая мысль». Друзья добавили: «Завтра давайте и мы поищем новости в нашем городе!»"}},{"t":[[["その","その"]],[["夜","よる"],["、"],["ケン","ケン"],["は","は"]],[["おじいさん","おじいさん"],["に","に"],["「"],["どう","どう"],["して","して","する",3]],[["毎日","まいにち"]],[["いい","いい"]],[["ニュース","ニュース"],["が","が"]],[["ある","ある","ある",5],["ん","ん"],["です","です"],["か","か"],["」"],["と","と"]],[["聞きました","ききました","聞く",2],["。"],["おじいさん","おじいさん"],["は","は"],["「"],["毎日","まいにち"]],[["よく","よく"]],[["見ない","みない","見る",19],["と","と"],["、"],["見つからない","みつからない","見つからない",19],["ん","ん"],["だ","だ","です"],["よ","よ"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["そして","そして"],["、"],["「"],["でも","でも"],["、"],["今日","きょう"],["の","の"]],[["いちばん","いちばん"],["の","の"]],[["ニュース","ニュース"],["は","は"]],[["ケン","ケン"],["が","が"]],[["朝","あさ"]],[["早く","はやく","早い"]],[["起きた","おきた","起きる",0],["こと","こと"],["だ","だ","です"],["ね","ね"],["」"],["と","と"]],[["笑いました","わらいました","笑う",2],["。"],["ケン","ケン"],["は","は"],["「"],["それ","それ"],["は","は"]],[["ニュース","ニュース"],["じゃ","じゃ"]],[["ありません","ありません","ある",6],["！"],["」"],["と","と"]],[["言いました","いいました","言う",2],["。"],["でも","でも"],["、"],["二人","ふたり"],["は","は"]],[["いつ","いつ"],["まで","まで"],["も","も"]],[["笑っていました","わらっていました","笑う",15],["。"]]],"tr":{"az":"Həmin axşam Ken babasından soruşdu: «Necə olur ki, hər gün yaxşı xəbər tapırsan?» Babası dedi: «Hər gün diqqətlə baxmasan, onları görə bilməzsən». Sonra gülərək əlavə etdi: «Amma bu günün ən böyük xəbəri Kenin səhər tezdən oyanmasıdır!» Ken etiraz etdi: «Bu, xəbər deyil!» Amma ikisi də uzun müddət gülməyə davam etdi.","en":"That evening, Ken asked his grandfather, “How do you find good news every day?” Grandpa said, “If you don't look carefully every day, you won't find it.” Then he laughed and added, “But today's biggest news is that Ken woke up early!” Ken protested, “That's not news!” Yet they both kept laughing for a long time.","ru":"В тот вечер Кэн спросил дедушку: «Как тебе удаётся каждый день находить хорошие новости?» Дедушка ответил: «Если каждый день не смотреть внимательно, их не заметишь». Потом он засмеялся и добавил: «Но самая главная новость сегодня в том, что Кэн рано проснулся!» Кэн возразил: «Это не новость!» Однако они оба ещё долго смеялись."}}]}],"G":{"ああ":{"b":"ああ","p":"in","m":{"az":"aa, hə, ah","en":"ah, oh, I see","ru":"а, ах, понятно"},"n":{"az":"Təəccübü, anlamanı və ya hissi bildirə bilər.","en":"Can express surprise, understanding, or emotion.","ru":"Может выражать удивление, понимание или эмоцию."}},"あの":{"b":"あの","p":"dm","m":{"az":"o (uzaqdakı)","en":"that (over there)","ru":"тот (вдали)"},"n":{"az":"İsimdən əvvəl gəlir: あの人 = o adam, あの星 = o ulduz. Danışandan da, dinləyəndən də uzaq olan şey.","en":"Comes before a noun: あの人 = that person, あの星 = that star. Something far from both speakers.","ru":"Ставится перед существительным: あの人 = тот человек. Далеко от обоих собеседников."}},"あまり":{"b":"あまり","p":"ad","m":{"az":"o qədər də, çox da","en":"not very, not much","ru":"не очень, не особо"},"n":{"az":"Adətən inkarla işlənir: あまり寒くない = o qədər də soyuq deyil.","en":"Usually used with a negative: あまり寒くない = not very cold.","ru":"Обычно используется с отрицанием: あまり寒くない = не очень холодно."}},"ありがとう":{"b":"ありがとう","p":"ex","m":{"az":"sağ ol","en":"thank you","ru":"спасибо"},"n":{"az":"Daha nəzakətli: ありがとうございます.","en":"More polite: ありがとうございます.","ru":"Вежливее: ありがとうございます."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いいえ":{"b":"いいえ","p":"in","m":{"az":"xeyr, yox","en":"no","ru":"нет"}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いちばん":{"b":"一番 (いちばん)","p":"ad","m":{"az":"ən, birinci","en":"most, number one","ru":"самый, на первом месте"},"n":{"az":"Sifətlə üstünlük dərəcəsi yaradır: いちばん大きい - ən böyük.","en":"Forms a superlative with adjectives: いちばん大きい means the biggest.","ru":"Образует превосходную степень с прилагательными: いちばん大きい - самый большой."}},"いっしょ":{"b":"一緒 (いっしょ)","p":"n","m":{"az":"birlikdə","en":"together","ru":"вместе"},"n":{"az":"いっしょに = birlikdə.","en":"いっしょに = together.","ru":"いっしょに = вместе."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"おじいさん":{"b":"おじいさん","p":"n","m":{"az":"baba; qoca kişi","en":"grandfather; old man","ru":"дедушка; старик"}},"おもしろい":{"b":"おもしろい","p":"ai","m":{"az":"maraqlı, əyləncəli","en":"interesting, amusing","ru":"интересный, забавный"},"n":{"az":"い-sifətdir və həm maraqlı, həm də gülməli mənasında işlənə bilər.","en":"An i-adjective that can mean either interesting or amusing.","ru":"Прилагательное на い, которое может означать интересный или забавный."}},"お姉さん":{"b":"お姉さん (おねえさん)","p":"n","m":{"az":"böyük bacı, gənc xanım","en":"older sister, young woman","ru":"старшая сестра, девушка"},"n":{"az":"Başqasının böyük bacısı haqqında və ya böyük bacıya, bəzən də gənc qadına müraciətdə işlənir.","en":"Used for someone else's older sister, to address an older sister, or sometimes a young woman.","ru":"Употребляется о чужой старшей сестре, при обращении к старшей сестре, иногда к молодой женщине."}},"お祝い":{"b":"お祝い (おいわい)","p":"n","m":{"az":"təbrik, bayram hədiyyəsi, qeyd etmə","en":"celebration, congratulations, celebratory gift","ru":"празднование, поздравление, подарок"},"n":{"az":"お祝いする - qeyd etmək və ya təbrik etmək.","en":"お祝いする means to celebrate or congratulate.","ru":"お祝いする означает праздновать или поздравлять."}},"お祭り":{"b":"お祭り (おまつり)","p":"n","m":{"az":"bayram; festival","en":"festival; celebration","ru":"праздник; фестиваль"},"n":{"az":"お nəzakət bildirən ön şəkilçidir; 祭り də işlənir.","en":"お is a polite prefix; 祭り is also used.","ru":"お является вежливой приставкой; также употребляется 祭り."}},"お茶":{"b":"お茶 (おちゃ)","p":"n","m":{"az":"çay","en":"tea","ru":"чай"}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"くださる":{"b":"ください","p":"ex","m":{"az":"zəhmət olmasa (...edin)","en":"please (do ...)","ru":"пожалуйста (сделайте)"},"n":{"az":"Feilin te-formasından sonra nəzakətli xahiş: 見てください = baxın, zəhmət olmasa.","en":"After a te-form it makes a polite request: 見てください = please look.","ru":"После формы на -te – вежливая просьба: 見てください = посмотрите, пожалуйста."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"じゃ":{"b":"じゃ (← では)","p":"cp","m":{"az":"inkarın birinci hissəsi","en":"first part of the negative","ru":"первая часть отрицания"},"n":{"az":"じゃ ありません birlikdə 'deyil' deməkdir: 学生じゃ ありません = tələbə deyiləm. Rəsmi yazıda では ありません.","en":"じゃ ありません together means 'is not': 学生じゃ ありません = I am not a student. Formal writing: では ありません.","ru":"じゃ ありません вместе = 'не является': 学生じゃ ありません = я не студент. В официальной речи では ありません."}},"すぐ":{"b":"すぐ","p":"ad","m":{"az":"tez, dərhal","en":"soon, immediately","ru":"сразу, скоро"},"n":{"az":"すぐに = dərhal.","en":"すぐに = right away.","ru":"すぐに = сразу."}},"すごい":{"b":"すごい","p":"ai","m":{"az":"möhtəşəm; heyrətamiz","en":"amazing; incredible","ru":"потрясающий; удивительный"},"n":{"az":"い-sifətdir və danışıqda heyrət ifadə edir.","en":"It is an i-adjective often used to express amazement.","ru":"Это i-прилагательное, часто выражающее восхищение."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"ずつ":{"b":"ずつ","p":"pt","m":{"az":"...-ar, hərəsi bir","en":"each, apiece","ru":"по (одному)"},"n":{"az":"一つずつ = hərəsi bir dənə.","en":"一つずつ = one each.","ru":"一つずつ = по одному."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"そば":{"b":"そば","p":"n","m":{"az":"yan, yaxınlıq","en":"side, nearby","ru":"рядом, около"},"n":{"az":"N の そば = N-in yanında.","en":"N の そば = beside N.","ru":"N の そば = рядом с N."}},"それ":{"b":"それ","p":"pr","m":{"az":"o; həmin şey","en":"that; that thing","ru":"то; эта вещь"},"n":{"az":"Dinləyənə yaxın və ya əvvəl qeyd edilmiş şeyi bildirir.","en":"Refers to something near the listener or already mentioned.","ru":"Указывает на предмет рядом со слушающим или на уже упомянутое."}},"だけ":{"b":"だけ","p":"pt","m":{"az":"yalnız, ancaq","en":"only, just","ru":"только"},"n":{"az":"一度だけ = bircə dəfə; まんなかの星だけ = yalnız ortadakı ulduz.","en":"一度だけ = just once.","ru":"一度だけ = только один раз."}},"だめ":{"b":"駄目 (だめ)","p":"an","m":{"az":"olmaz; yararsız","en":"not allowed; no good","ru":"нельзя; негодный"},"n":{"az":"Na-sifətdir; tək işlənən だめ qadağa və ya etiraz bildirə bilər.","en":"A na-adjective; used alone, だめ can express prohibition or objection.","ru":"На-прилагательное; отдельно だめ может выражать запрет или возражение."}},"だれ":{"b":"だれ","p":"pr","m":{"az":"kim","en":"who","ru":"кто"},"n":{"az":"Sual sözü: あの人はだれですか = O adam kimdir? Daha nəzakətli forması どなた.","en":"Question word: あの人はだれですか = Who is that person? More polite: どなた.","ru":"Вопросительное слово: あの人はだれですか = Кто этот человек? Вежливее: どなた."}},"つける":{"b":"付ける (つける)","p":"v","m":{"az":"qoymaq (ad), taxmaq","en":"to give (a name), attach","ru":"давать (имя), прикреплять"},"n":{"az":"名前をつける = ad qoymaq.","en":"名前をつける = give a name.","ru":"名前をつける = дать имя."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"どう":{"b":"どう","p":"ad","m":{"az":"necə, nə cür","en":"how, in what way","ru":"как, каким образом"},"n":{"az":"どうですか = necədir, nə fikirləşirsiniz?","en":"どうですか asks how something is or what someone thinks.","ru":"どうですか означает «как это?» или «что вы думаете?»."}},"どうぞ":{"b":"どうぞ","p":"ad","m":{"az":"buyurun; xahiş edirəm","en":"please","ru":"пожалуйста"},"n":{"az":"どうぞ よろしく = tanışlığımıza şadam (tanışlığın sonu).","en":"どうぞ よろしく = nice to meet you (end of an introduction).","ru":"どうぞ よろしく = рад знакомству (в конце представления)."}},"ない":{"b":"無い (ない)","p":"ai","m":{"az":"yoxdur; mövcud deyil","en":"not exist; not have","ru":"нет; отсутствует"},"n":{"az":"İ-sifət kimi dəyişir: なく və なかった; felə qoşulduqda inkar da bildirir.","en":"Inflects like an i-adjective: なく and なかった; attached to a verb, it also marks negation.","ru":"Изменяется как и-прилагательное: なく и なかった; при глаголе также выражает отрицание."}},"なさる":{"b":"なさる","p":"v","m":{"az":"etmək (hörmətli forma)","en":"to do (honorific)","ru":"делать (уважительная форма)"},"n":{"az":"する felinin hörmətli formasıdır; なさい əmr və göstərişlərdə işlənir.","en":"Honorific form of する; なさい is used for instructions and commands.","ru":"Уважительная форма する; なさい используется в указаниях и приказах."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"にこにこ":{"b":"にこにこ","p":"ad","m":{"az":"gülümsəyərək","en":"with a cheerful smile","ru":"с улыбкой"},"n":{"az":"にこにこする = gülümsəmək, adətən səssiz və şən şəkildə.","en":"にこにこする means to smile cheerfully, usually without laughing aloud.","ru":"にこにこする означает приветливо улыбаться, обычно без громкого смеха."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"ひみつ":{"b":"秘密 (ひみつ)","p":"n","m":{"az":"sirr; gizli məlumat","en":"secret","ru":"секрет; тайна"},"n":{"az":"秘密の söz birləşməsi gizli mənasını verir.","en":"秘密の means secret or confidential before a noun.","ru":"秘密の перед существительным означает тайный или секретный."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ほう":{"b":"方 (ほう)","p":"n","m":{"az":"tərəf, istiqamət, seçim","en":"side, direction, option","ru":"сторона, направление, вариант"},"n":{"az":"〜のほう müqayisədə üstün tutulan tərəfi bildirə bilər.","en":"〜のほう can indicate the preferred side in a comparison.","ru":"〜のほう может указывать на предпочтительный вариант при сравнении."}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みなさん":{"b":"皆さん (みなさん)","p":"n","m":{"az":"hamınız, hörmətli dinləyicilər","en":"everyone","ru":"все (вы)"}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もっと":{"b":"もっと","p":"ad","m":{"az":"daha, daha çox","en":"more","ru":"больше, ещё"}},"や":{"b":"や","p":"pt","m":{"az":"və, ... kimi","en":"and, things such as","ru":"и, например"},"n":{"az":"や tam olmayan siyahı yaradır: 犬や猫（など）; nida və çağırışda da işlənir: おや、太郎や.","en":"や gives a non-exhaustive list, 犬や猫（など）, and also appears in exclamations or calls, おや、太郎や.","ru":"や обозначает неполный перечень, 犬や猫（など）, а также встречается в восклицаниях и обращениях: おや、太郎や."}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"より":{"b":"より","p":"pt","m":{"az":"-dan/-dən daha (müqayisə)","en":"than","ru":"чем"},"n":{"az":"さっきより明るく = bayaqkından daha parlaq.","en":"さっきより明るく = brighter than before.","ru":"さっきより明るく = ярче, чем раньше."}},"わたし":{"b":"わたし (私)","p":"pr","m":{"az":"mən","en":"I, me","ru":"я"},"n":{"az":"Ən çox işlənən neytral 'mən'.","en":"The most common neutral 'I'.","ru":"Самое употребительное нейтральное 'я'."}},"わたしたち":{"b":"私たち (わたしたち)","p":"pr","m":{"az":"biz","en":"we, us","ru":"мы, нас"}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"ん":{"b":"ん (← の)","p":"pt","m":{"az":"(izah bildirir)","en":"(explanatory)","ru":"(пояснение)"},"n":{"az":"〜んです / 〜のです: səbəb və ya izah verəndə işlənir; danışıqda の → ん.","en":"〜んです / 〜のです adds an explanation; in speech の becomes ん.","ru":"〜んです / 〜のです – объяснение; в речи の → ん."}},"ケン":{"b":"ケン","p":"nm","m":{"az":"Ken (oğlan adı)","en":"Ken (boy's name)","ru":"Кен (мужское имя)"}},"テレビ":{"b":"テレビ","p":"n","m":{"az":"televizor, televiziya","en":"television, TV set","ru":"телевидение, телевизор"}},"メモ":{"b":"メモ (めも)","p":"n","m":{"az":"qeyd, qısa yazı","en":"note, memo","ru":"заметка, записка"}},"一人":{"b":"一人 (ひとり)","p":"n","m":{"az":"tək, bir nəfər","en":"alone; one person","ru":"один (человек)"},"n":{"az":"一人で = təkbaşına.","en":"一人で = alone.","ru":"一人で = в одиночку."}},"一週間":{"b":"一週間 (いっしゅうかん)","p":"ex","m":{"az":"bir həftə","en":"one week","ru":"одна неделя"},"n":{"az":"Müddət bildirir, 一週間に一回 həftədə bir dəfə deməkdir.","en":"Expresses duration, and 一週間に一回 means once a week.","ru":"Обозначает длительность, 一週間に一回 значит один раз в неделю."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"不思議":{"b":"不思議 (ふしぎ)","p":"an","m":{"az":"sirli; qəribə","en":"mysterious; curious","ru":"загадочный; удивительный"},"n":{"az":"な-sifətidir: 不思議な話; isim kimi «sirr, möcüzə» də bildirir.","en":"A な-adjective: 不思議な話; as a noun it can mean a mystery or wonder.","ru":"な-прилагательное: 不思議な話; как существительное может означать тайну или чудо."}},"世界":{"b":"世界 (せかい)","p":"n","m":{"az":"dünya, aləm","en":"world","ru":"мир"}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"乗る":{"b":"乗る (のる)","p":"v","m":{"az":"minmək","en":"board, ride","ru":"садиться в транспорт, ехать"},"n":{"az":"Nəqliyyat vasitəsi に ilə işlənir: 電車に乗る “qatara minmək”.","en":"The vehicle takes に: 電車に乗る means “board a train.”","ru":"Транспорт обозначается с に: 電車に乗る «сесть в поезд»."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"人たち":{"b":"人たち (ひとたち)","p":"n","m":{"az":"adamlar, camaat","en":"people","ru":"люди"}},"今":{"b":"今 (いま)","p":"n","m":{"az":"indi","en":"now","ru":"сейчас"},"n":{"az":"今も = indi də.","en":"今も = even now.","ru":"今も = и сейчас."}},"今年":{"b":"今年 (ことし)","p":"n","m":{"az":"bu il","en":"this year","ru":"в этом году"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 今年行きます.","en":"Usually takes no に as a time expression: 今年行きます.","ru":"При обозначении времени обычно употребляется без に: 今年行きます."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"休む":{"b":"休む (やすむ)","p":"v","m":{"az":"istirahət etmək, işə və ya dərsə getməmək","en":"rest, take time off","ru":"отдыхать, пропускать работу или занятия"},"n":{"az":"学校を休む “dərsə getməmək”, 会社を休む isə “işə getməmək” deməkdir.","en":"学校を休む means “miss school,” and 会社を休む means “take time off work.”","ru":"学校を休む означает «пропускать занятия», а 会社を休む означает «не идти на работу»."}},"会":{"b":"会 (かい)","p":"n","m":{"az":"toplantı, yığıncaq, tədbir","en":"meeting, gathering, event","ru":"собрание, встреча, мероприятие"}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"優しい":{"b":"優しい (やさしい)","p":"ai","m":{"az":"mehriban, mülayim","en":"kind, gentle","ru":"добрый, мягкий"},"n":{"az":"İ-sifətidir; “asan” mənasındakı 易しい ilə eyni oxunur.","en":"An i-adjective; it has the same reading as 易しい “easy.”","ru":"Прилагательное на い; читается так же, как 易しい «лёгкий»."}},"元気":{"b":"元気 (げんき)","p":"an","m":{"az":"gümrah; sağlam","en":"energetic; well","ru":"бодрый; здоровый"},"n":{"az":"な-sifətidir: 元気な子; 元気です = özünü yaxşı hiss edir.","en":"A な-adjective: 元気な子; 元気です means being well.","ru":"な-прилагательное: 元気な子; 元気です означает хорошее самочувствие."}},"先":{"b":"先 (さき)","p":"n","m":{"az":"uc, son; qabaq","en":"end, tip; ahead","ru":"конец; впереди"},"n":{"az":"道の先 = yolun sonu.","en":"道の先 = the end of the path.","ru":"道の先 = конец дороги."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"公園":{"b":"公園 (こうえん)","p":"n","m":{"az":"park","en":"park","ru":"парк"}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"初めて":{"b":"初めて (はじめて)","p":"ad","m":{"az":"ilk dəfə","en":"for the first time","ru":"впервые"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"力":{"b":"力 (ちから)","p":"n","m":{"az":"güc; qüvvə","en":"strength; power","ru":"сила; мощь"}},"助ける":{"b":"助ける (たすける)","p":"v","m":{"az":"kömək etmək; xilas etmək","en":"help; rescue","ru":"помогать; спасать"},"n":{"az":"Təsirli feldir və kömək edilən şəxs を ilə göstərilir; 助かる xilas olmaq deməkdir.","en":"A transitive verb with the person helped marked by を; 助かる means to be saved.","ru":"Переходный глагол: человек, которому помогают, оформляется を; 助かる означает спастись."}},"動く":{"b":"動く (うごく)","p":"v","m":{"az":"hərəkət etmək, işləmək","en":"to move, to operate","ru":"двигаться, работать"},"n":{"az":"I qrup feldir: 動きました = hərəkət etdi; 動かす = hərəkət etdirmək.","en":"A Group 1 verb: 動きました = moved; 動かす = to move something.","ru":"Глагол I группы: 動きました = двигался; 動かす = приводить в движение."}},"友達":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг"}},"同じ":{"b":"同じ (おなじ)","p":"an","m":{"az":"eyni","en":"same","ru":"одинаковый, тот же"},"n":{"az":"İsimdən əvvəl な almır: 同じ月 = eyni Ay.","en":"Takes no な before a noun: 同じ月 = the same moon.","ru":"Перед сущ. без な: 同じ月 = та же луна."}},"喜ぶ":{"b":"喜ぶ (よろこぶ)","p":"v","m":{"az":"sevinmək, şadlanmaq","en":"to rejoice, to be pleased","ru":"радоваться, обрадоваться"},"n":{"az":"I qrup feldir: 喜びました = sevindi; プレゼントを喜ぶ = hədiyyəyə sevinmək.","en":"A Group 1 verb: 喜びました = was pleased; プレゼントを喜ぶ = to be delighted with a gift.","ru":"Глагол I группы: 喜びました = обрадовался; プレゼントを喜ぶ = радоваться подарку."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"夕方":{"b":"夕方 (ゆうがた)","p":"n","m":{"az":"axşamüstü","en":"evening","ru":"вечер"}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大切":{"b":"大切 (たいせつ)","p":"an","m":{"az":"vacib, əziz","en":"important, precious","ru":"важный, дорогой"},"n":{"az":"Na-sifətidir: 大切な物 “əziz əşya”; 大切にする “qayğı ilə yanaşmaq, əziz tutmaq” deməkdir.","en":"A na-adjective: 大切な物 “a precious thing”; 大切にする means “cherish or take good care of.”","ru":"Прилагательное на な: 大切な物 «дорогая вещь»; 大切にする означает «беречь, дорожить»."}},"天気":{"b":"天気 (てんき)","p":"n","m":{"az":"hava, hava şəraiti","en":"weather","ru":"погода"}},"奥":{"b":"奥 (おく)","p":"n","m":{"az":"içəri tərəf; dərinlik","en":"inner part; back","ru":"глубина; дальняя часть"},"n":{"az":"Yerə görə otağın içəri tərəfini, mağazanın arxasını və ya meşənin dərinliyini bildirir.","en":"Depending on the place, it means the inner part of a room, the back of a shop, or deep inside a forest.","ru":"В зависимости от места обозначает глубину комнаты, дальнюю часть магазина или глубь леса."}},"女の子":{"b":"女の子 (おんなのこ)","p":"n","m":{"az":"qız uşağı","en":"girl","ru":"девочка"}},"始める":{"b":"始める (はじめる)","p":"v","m":{"az":"başlamaq, başlatmaq","en":"to begin, to start something","ru":"начинать"},"n":{"az":"Təsirli feldir, 勉強を始めます dərsə başlamaqdır, təsirsiz qarşılığı 始まる-dur.","en":"Transitive: 勉強を始めます means start studying, while 始まる is intransitive.","ru":"Переходный глагол: 勉強を始めます - начать учёбу, непереходный вариант 始まる."}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"寒い":{"b":"寒い (さむい)","p":"ai","m":{"az":"soyuq","en":"cold, chilly","ru":"холодный, прохладный"},"n":{"az":"い-sifətdir; əsasən hava üçün işlənir, toxunanda soyuq əşyalar üçün 冷たい deyilir.","en":"An i-adjective mainly for cold weather; use 冷たい for cold objects.","ru":"Прилагательное на い, обычно о погоде; для холодных предметов используют 冷たい."}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"少女":{"b":"少女 (しょうじょ)","p":"n","m":{"az":"qız uşağı, yeniyetmə qız","en":"young girl","ru":"девочка, юная девушка"}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"川":{"b":"川 (かわ)","p":"n","m":{"az":"çay","en":"river","ru":"река"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"幸せ":{"b":"幸せ (しあわせ)","p":"an","m":{"az":"xoşbəxtlik, xoşbəxt","en":"happiness, happy","ru":"счастье, счастливый"},"n":{"az":"な-sifətdir; 幸せな人 - xoşbəxt insan.","en":"A na-adjective; 幸せな人 means a happy person.","ru":"Это na-прилагательное; 幸せな人 - счастливый человек."}},"広場":{"b":"広場 (ひろば)","p":"n","m":{"az":"meydan, açıq sahə","en":"square, open space","ru":"площадь, открытое пространство"}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"形":{"b":"形 (かたち)","p":"n","m":{"az":"forma, şəkil","en":"shape, form","ru":"форма"}},"役":{"b":"役 (やく)","p":"n","m":{"az":"rol, vəzifə","en":"role, duty","ru":"роль, обязанность"},"n":{"az":"役に立つ sabit ifadəsi “faydalı olmaq” deməkdir.","en":"The set phrase 役に立つ means “be useful.”","ru":"Устойчивое выражение 役に立つ означает «быть полезным»."}},"心":{"b":"心 (こころ)","p":"n","m":{"az":"ürək, qəlb, könül","en":"heart, mind, spirit","ru":"сердце, душа, разум"},"n":{"az":"Burada fiziki orqandan çox hiss və düşüncəni bildirir.","en":"Usually refers to feelings or the mind rather than the physical organ.","ru":"Обычно обозначает чувства или душу, а не физический орган."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急":{"b":"急 (きゅう)","p":"an","m":{"az":"qəfil, birdən","en":"sudden","ru":"внезапный"},"n":{"az":"急に = birdən, qəfildən.","en":"急に = suddenly.","ru":"急に = вдруг."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"新しい":{"b":"新しい (あたらしい)","p":"ai","m":{"az":"yeni","en":"new","ru":"новый"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"早い":{"b":"早い (はやい)","p":"ai","m":{"az":"erkən; tez","en":"early","ru":"ранний; рано"},"n":{"az":"い-sifətidir; 早く zərf formasıdır, sürət mənasında isə 速い yazılır.","en":"An い-adjective; 早く is its adverb form, while 速い refers to speed.","ru":"い-прилагательное; 早く является наречной формой, а 速い обозначает скорость."}},"明るい":{"b":"明るい (あかるい)","p":"ai","m":{"az":"işıqlı, parlaq","en":"bright","ru":"светлый, яркий"},"n":{"az":"明るく光る = parlaq işıq saçmaq.","en":"明るく光る = shine brightly.","ru":"明るく光る = ярко светиться."}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"昨日":{"b":"昨日 (きのう)","p":"n","m":{"az":"dünən","en":"yesterday","ru":"вчера"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 昨日来ました.","en":"Usually takes no に as a time expression: 昨日来ました.","ru":"При обозначении времени обычно употребляется без に: 昨日来ました."}},"時":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, zaman","en":"time, occasion","ru":"время, момент"},"n":{"az":"時 “vaxt” mənasında とき, saat bildirən rəqəmdən sonra isə じ oxunur: 三時 “saat üç”.","en":"時 is read とき for “time” but じ after a number indicating the hour: 三時 “three o'clock.”","ru":"時 читается とき в значении «время», но じ после числа, обозначающего час: 三時 «три часа»."}},"暑い":{"b":"暑い (あつい)","p":"ai","m":{"az":"isti (hava haqqında)","en":"hot (weather)","ru":"жаркий (о погоде)"},"n":{"az":"い-sifətdir; 暑かった keçmiş zaman formasıdır.","en":"An i-adjective; 暑かった is its past form.","ru":"Это i-прилагательное; 暑かった - форма прошедшего времени."}},"暖かい":{"b":"暖かい (あたたかい)","p":"ai","m":{"az":"isti, ilıq","en":"warm","ru":"тёплый"},"n":{"az":"İ-sifətidir; əsasən hava və mühitin istiliyini, 温かい isə əşya, yemək və münasibətin istiliyini bildirir.","en":"An i-adjective mainly describing warm weather or surroundings; 温かい is used for objects, food, and personal warmth.","ru":"Прилагательное на い, обычно о тёплой погоде или обстановке; 温かい употребляется о предметах, еде и душевном тепле."}},"書く":{"b":"書く (かく)","p":"v","m":{"az":"yazmaq","en":"to write","ru":"писать"},"n":{"az":"「森」と書く = «Mori» yazmaq. 書いてある = yazılıb (yazılı durur).","en":"「森」と書く = write \"Mori\". 書いてある = is written.","ru":"「森」と書く = написать «Мори». 書いてある = написано."}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"歩く":{"b":"歩く (あるく)","p":"v","m":{"az":"yerimək; piyada getmək","en":"walk","ru":"ходить; идти пешком"},"n":{"az":"歩いて piyada deməkdir; keçilən yol を ilə göstərilə bilər: 道を歩く.","en":"歩いて means on foot; the route can take を: 道を歩く.","ru":"歩いて означает пешком; путь может оформляться を: 道を歩く."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"気":{"b":"気 (き)","p":"n","m":{"az":"ruh, əhval, niyyət","en":"spirit, mood, intention","ru":"дух, настроение, намерение"},"n":{"az":"気をつける = diqqətli olmaq; 気になる = maraqlandırmaq və ya narahat etmək.","en":"気をつける = to be careful; 気になる = to be curious or concerned.","ru":"気をつける = быть осторожным; 気になる = интересовать или беспокоить."}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"犬":{"b":"犬 (いぬ)","p":"n","m":{"az":"it","en":"dog","ru":"собака"}},"男":{"b":"男 (おとこ)","p":"n","m":{"az":"kişi","en":"man, male","ru":"мужчина"},"n":{"az":"Nəzakətli gündəlik nitqdə kişi üçün çox vaxt 男の人 işlənir.","en":"男の人 is often used for a man in polite everyday speech.","ru":"В вежливой повседневной речи о мужчине часто говорят 男の人."}},"男の子":{"b":"男の子 (おとこのこ)","p":"n","m":{"az":"oğlan","en":"boy","ru":"мальчик"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"疲れる":{"b":"疲れる (つかれる)","p":"v","m":{"az":"yorulmaq","en":"to get tired","ru":"уставать"},"n":{"az":"疲れました - yoruldum; 疲れています - yorğunam.","en":"疲れました means got tired; 疲れています means am tired.","ru":"疲れました означает устал; 疲れています - я устал и сейчас чувствую усталость."}},"目":{"b":"目 (め)","p":"n","m":{"az":"göz","en":"eye","ru":"глаз"}},"着る":{"b":"着る (きる)","p":"v","m":{"az":"geyinmək (paltar)","en":"to wear, put on","ru":"надевать"},"n":{"az":"白い服を着たねこ = ağ paltar geyinmiş pişik (feil təyin kimi).","en":"白い服を着たねこ = a cat wearing white.","ru":"白い服を着たねこ = кошка в белом."}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"立つ":{"b":"立つ (たつ)","p":"v","m":{"az":"dayanmaq, ayağa qalxmaq","en":"to stand","ru":"стоять, вставать"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"紙":{"b":"紙 (かみ)","p":"n","m":{"az":"kağız","en":"paper","ru":"бумага"}},"練習":{"b":"練習 (れんしゅう)","p":"n","m":{"az":"məşq, praktika","en":"practice, training","ru":"практика, тренировка"},"n":{"az":"練習する = məşq etmək; ピアノの練習 = piano məşqi.","en":"練習する = to practice; ピアノの練習 = piano practice.","ru":"練習する = тренироваться; ピアノの練習 = занятие на пианино."}},"置く":{"b":"置く (おく)","p":"v","m":{"az":"qoymaq","en":"to put, place","ru":"класть, ставить"}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"脱ぐ":{"b":"脱ぐ (ぬぐ)","p":"v","m":{"az":"əynindən çıxarmaq, ayağından çıxarmaq","en":"take off clothing or footwear","ru":"снимать одежду или обувь"},"n":{"az":"Geyim və ayaqqabı を ilə işlənir; て-forması 脱いで olur.","en":"Clothing or footwear takes を; the て-form is 脱いで.","ru":"Одежда или обувь обозначается с を; форма на て: 脱いで."}},"自転車":{"b":"自転車 (じてんしゃ)","p":"n","m":{"az":"velosiped","en":"bicycle","ru":"велосипед"}},"花":{"b":"花 (はな)","p":"n","m":{"az":"çiçək","en":"flower","ru":"цветок"}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見せる":{"b":"見せる (みせる)","p":"v","m":{"az":"göstərmək","en":"show","ru":"показывать"},"n":{"az":"人に物を見せる kiməsə nəyisə göstərmək quruluşudur.","en":"Use 人に物を見せる to show something to someone.","ru":"Конструкция 人に物を見せる означает показать что-либо кому-либо."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"話":{"b":"話 (はなし)","p":"n","m":{"az":"söhbət, hekayə","en":"conversation, story","ru":"разговор, история"}},"話す":{"b":"話す (はなす)","p":"v","m":{"az":"danışmaq; söhbət etmək","en":"to speak; to talk","ru":"говорить; разговаривать"},"n":{"az":"Dil を, həmsöhbət と ilə göstərilir: 日本語を話す, 友達と話す.","en":"A language takes を and a conversation partner takes と: 日本語を話す, 友達と話す.","ru":"Язык обозначается через を, собеседник через と: 日本語を話す, 友達と話す."}},"調べる":{"b":"調べる (しらべる)","p":"v","m":{"az":"araşdırmaq, yoxlamaq","en":"to investigate, to check, to look up","ru":"исследовать, проверять, искать сведения"},"n":{"az":"Söz və məlumat axtarışında da işlənir: 辞書で調べます.","en":"Also used to look up information: 辞書で調べます means to check in a dictionary.","ru":"Также используется для поиска сведений: 辞書で調べます - посмотреть в словаре."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"走る":{"b":"走る (はしる)","p":"v","m":{"az":"qaçmaq","en":"run","ru":"бежать"},"n":{"az":"る ilə bitsə də birinci qrup feldir; 走らせる qaçırmaq, 車を走らせる isə maşını sürmək deməkdir.","en":"Despite ending in る, it is a group 1 verb; 走らせる means make run, and 車を走らせる means drive a car.","ru":"Несмотря на る, это глагол первой группы; 走らせる означает заставить бежать, а 車を走らせる вести машину."}},"起きる":{"b":"起きる (おきる)","p":"v","m":{"az":"oyanmaq; yataqdan qalxmaq","en":"to wake up; to get up","ru":"просыпаться; вставать"},"n":{"az":"Təsirsizdir; 起こす kimisə oyatmaq deməkdir.","en":"Intransitive; 起こす means to wake someone up.","ru":"Непереходный; 起こす означает будить кого-то."}},"近く":{"b":"近く (ちかく)","p":"n","m":{"az":"yaxınlıq, yaxın yer","en":"vicinity, nearby place","ru":"окрестности, близкое место"},"n":{"az":"Nの近く “N-in yaxınlığı”, 近くに isə “yaxınlıqda” deməkdir.","en":"Nの近く means “near N,” and 近くに means “nearby.”","ru":"Nの近く означает «рядом с N», а 近くに означает «поблизости»."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"降る":{"b":"降る (ふる)","p":"v","m":{"az":"yağmaq","en":"fall as rain or snow","ru":"идти о дожде или снеге"},"n":{"az":"Yağıntı が ilə göstərilir: 雨が降る, 雪が降る.","en":"Precipitation takes が: 雨が降る, 雪が降る.","ru":"Осадки оформляются が: 雨が降る, 雪が降る."}},"雨":{"b":"雨 (あめ)","p":"n","m":{"az":"yağış","en":"rain","ru":"дождь"}},"雲":{"b":"雲 (くも)","p":"n","m":{"az":"bulud","en":"cloud","ru":"облако"}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"飲む":{"b":"飲む (のむ)","p":"v","m":{"az":"içmək","en":"drink","ru":"пить"},"n":{"az":"Dərman qəbul etmək üçün də işlənir: 薬を飲む.","en":"Also used for taking medicine: 薬を飲む.","ru":"Также употребляется для приёма лекарства: 薬を飲む."}},"黒い":{"b":"黒い (くろい)","p":"ai","m":{"az":"qara","en":"black","ru":"чёрный"},"n":{"az":"İ-sifətdir; rəngin isim forması 黒 olur.","en":"An i-adjective; the noun for the color is 黒.","ru":"И-прилагательное; существительное для цвета: 黒."}}}};